package com.vibeguard.samples.files;
import java.util.*; import java.util.concurrent.ConcurrentHashMap; import org.springframework.core.io.ByteArrayResource; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile;
/** Stores uploaded document bytes and metadata for the current process only. */ @RestController @RequestMapping("/api/files") public class FileController { private final Map<String,StoredFile> files=new ConcurrentHashMap<>(); @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ResponseEntity<Metadata> upload(@RequestParam MultipartFile file)throws Exception{if(file.isEmpty())return ResponseEntity.badRequest().build();String id=UUID.randomUUID().toString();StoredFile stored=new StoredFile(id,Optional.ofNullable(file.getOriginalFilename()).orElse("upload"),file.getContentType(),file.getBytes());files.put(id,stored);return ResponseEntity.status(201).body(Metadata.from(stored));} @GetMapping public List<Metadata> list(){return files.values().stream().map(Metadata::from).toList();} @GetMapping("/{id}/content") public ResponseEntity<ByteArrayResource> download(@PathVariable String id){StoredFile file=files.get(id);if(file==null)return ResponseEntity.notFound().build();return ResponseEntity.ok().contentType(MediaType.parseMediaType(Optional.ofNullable(file.contentType()).orElse(MediaType.APPLICATION_OCTET_STREAM_VALUE))).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+file.name()+"\"").body(new ByteArrayResource(file.bytes()));} record StoredFile(String id,String name,String contentType,byte[] bytes){} record Metadata(String id,String name,long size){static Metadata from(StoredFile file){return new Metadata(file.id(),file.name(),file.bytes().length);}} }
